import{_ as e,C as r,c as i,o as t,j as l,G as n,a0 as a,b as s,a as o,w as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Sessionsguide: Introduktion til mentalt spil (2-3 timer)","description":"","frontmatter":{},"headers":[],"relativePath":"da/mental-journey/session-guide.md","filePath":"da/mental-journey/session-guide.md"}');const p=e({name:"da/mental-journey/session-guide.md"},[["render",function(e,g,p,k,m,h){const f=r("AdBanner"),v=r("Mermaid"),c=r("AdInArticle");return t(),i("div",null,[g[1]||(g[1]=l("h1",{id:"sessionsguide-introduktion-til-mentalt-spil-2-3-timer",tabindex:"-1"},[o("Sessionsguide: Introduktion til mentalt spil (2-3 timer) "),l("a",{class:"header-anchor",href:"#sessionsguide-introduktion-til-mentalt-spil-2-3-timer","aria-label":'Permalink to "Sessionsguide: Introduktion til mentalt spil (2-3 timer)"'},"​")],-1)),n(f),g[2]||(g[2]=a('<h2 id="oversigt" tabindex="-1">Oversigt <a class="header-anchor" href="#oversigt" aria-label="Permalink to &quot;Oversigt&quot;">​</a></h2><p>Denne guide hjælper dig med at gennemføre en 2-3 timers introduktionssession om mental spiltræning for petanquespillere. Perfekt til trænere, klubledere eller erfarne spillere, der ønsker at introducere mental træning til deres hold.</p><div class="tip custom-block"><p class="custom-block-title">To afsnit i denne vejledning</p><ul><li><strong><a href="#for-participants">For deltagere</a></strong> - Hvad spillerne vil lære</li><li><strong><a href="#for-facilitators">For facilitatorer</a></strong> - Sådan afholdes sessionen</li></ul></div><h2 id="hurtig-adgang" tabindex="-1">Hurtig adgang <a class="header-anchor" href="#hurtig-adgang" aria-label="Permalink to &quot;Hurtig adgang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Afsnit</th><th>Formål</th><th>Adgang</th></tr></thead><tbody><tr><td><strong>For deltagere</strong></td><td>Hvad du kan forvente af sessionen</td><td><a href="#for-deltagere">Se sektion</a></td></tr><tr><td><strong>For facilitatorer</strong></td><td>Fuld sessionsplan og tidsplan</td><td><a href="#for-facilitatorer">Se sektion</a></td></tr><tr><td><strong>Materialer til sessionen</strong></td><td>Guider, slides og arbejdsark</td><td><a href="/da/mental-journey/materialer">Se materialer</a></td></tr><tr><td><strong>Forberedelsestjekliste</strong></td><td>Hvad skal man forberede inden sessionen</td><td><a href="#forberedelse-1-uge-før">Se tjekliste</a></td></tr></tbody></table><hr><h2 id="for-deltagere" tabindex="-1">For deltagere <a class="header-anchor" href="#for-deltagere" aria-label="Permalink to &quot;For deltagere&quot;">​</a></h2><h3 id="hvad-man-kan-forvente" tabindex="-1">Hvad man kan forvente <a class="header-anchor" href="#hvad-man-kan-forvente" aria-label="Permalink to &quot;Hvad man kan forvente&quot;">​</a></h3><p>Denne session introducerer det mentale spil petanque gennem diskussion, øvelser og praktiske teknikker, du kan bruge med det samme.</p><p><strong>Du vil lære:</strong></p><ul><li>Hvorfor mental træning er vigtig for præstation</li><li>Forskellen mellem &quot;teknisk tilstand&quot; og &quot;flowtilstand&quot;</li><li>Sådan genkender og håndterer du din indre kritiker</li><li>Enkle teknikker til trykhåndtering</li><li>En grundlæggende rutine før indtagelse</li></ul><p><strong>Hvad du skal bruge:</strong></p><ul><li>Åbent sind og villighed til at dele</li><li>Notesbog og pen</li><li>Dine egne erfaringer at diskutere</li><li>2-3 timers fokuseret tid</li></ul><h3 id="sessionsstruktur" tabindex="-1">Sessionsstruktur <a class="header-anchor" href="#sessionsstruktur" aria-label="Permalink to &quot;Sessionsstruktur&quot;">​</a></h3>',14)),(t(),s(u,null,{default:d(()=>[n(v,{id:"mermaid-157",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIndledning%20%3Cbr%2F%3E%2020%20minutter%5D%20--%3E%20B%5BZonen%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20B%20--%3E%20C%5BPause%20%3Cbr%2F%3E%2010%20minutter%5D%0A%20%20%20%20C%20--%3E%20D%5BIndre%20kritiker%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20D%20--%3E%20E%5BPraktiske%20v%C3%A6rkt%C3%B8jer%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegration%20%3Cbr%2F%3E%2020%20minutter%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:d(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[3]||(g[3]=a('<h3 id="nøglebegreber-du-vil-udforske" tabindex="-1">Nøglebegreber, du vil udforske <a class="header-anchor" href="#nøglebegreber-du-vil-udforske" aria-label="Permalink to &quot;Nøglebegreber, du vil udforske&quot;">​</a></h3><h4 id="_1-zonen-flowtilstand" tabindex="-1">1. Zonen (flowtilstand) <a class="header-anchor" href="#_1-zonen-flowtilstand" aria-label="Permalink to &quot;1. Zonen (flowtilstand)&quot;">​</a></h4><ul><li>Hvordan det føles, når alting klikker</li><li>Hvorfor det at tænke på teknik forstyrrer præstationen</li><li>&quot;Skiftet&quot; fra planlægning til udførelse</li></ul><h4 id="_2-den-indre-kritiker" tabindex="-1">2. Den indre kritiker <a class="header-anchor" href="#_2-den-indre-kritiker" aria-label="Permalink to &quot;2. Den indre kritiker&quot;">​</a></h4><ul><li>Hvordan negativ selvsnak påvirker præstationen</li><li>Forskellen mellem den indre kritiker og den indre coach</li><li>Neutral observation vs. hård dom</li></ul><h4 id="_3-trykrespons" tabindex="-1">3. Trykrespons <a class="header-anchor" href="#_3-trykrespons" aria-label="Permalink to &quot;3. Trykrespons&quot;">​</a></h4><ul><li>Hvorfor du spiller anderledes i konkurrencer</li><li>Fysiske tegn på tryk</li><li>Teknikker til hurtig nulstilling</li></ul><h4 id="_4-praktiske-værktøjer" tabindex="-1">4. Praktiske værktøjer <a class="header-anchor" href="#_4-praktiske-værktøjer" aria-label="Permalink to &quot;4. Praktiske værktøjer&quot;">​</a></h4><ul><li>3-åndedrætsnulstilling</li><li>Simpel rutine før indtagelse</li><li>Protokol til fejlretning</li></ul><h3 id="hvad-skal-man-medbringe" tabindex="-1">Hvad skal man medbringe <a class="header-anchor" href="#hvad-skal-man-medbringe" aria-label="Permalink to &quot;Hvad skal man medbringe&quot;">​</a></h3><p><strong>Påkrævet:</strong></p><ul><li>Dig selv og dine oplevelser</li><li>Villighed til at deltage</li></ul><p><strong>Valgfri:</strong></p><ul><li>Eksempler på mentale udfordringer, du står over for</li><li>Spørgsmål om specifikke situationer</li><li>Notesbog til personlige noter</li></ul><h3 id="efter-sessionen" tabindex="-1">Efter sessionen <a class="header-anchor" href="#efter-sessionen" aria-label="Permalink to &quot;Efter sessionen&quot;">​</a></h3><p>Du vil modtage:</p><ul><li>Opsummerende uddeling af nøglebegreber</li><li>Øvelser til ugen</li><li>Links til detaljerede uddannelsesmoduler</li><li>Målskabelon til mental spiludvikling</li></ul>',17)),n(c),g[4]||(g[4]=a('<hr><h2 id="for-facilitatorer" tabindex="-1">For facilitatorer <a class="header-anchor" href="#for-facilitatorer" aria-label="Permalink to &quot;For facilitatorer&quot;">​</a></h2><h3 id="forberedelsestjekliste" tabindex="-1">Forberedelsestjekliste <a class="header-anchor" href="#forberedelsestjekliste" aria-label="Permalink to &quot;Forberedelsestjekliste&quot;">​</a></h3><p><strong>1 uge før:</strong></p><ul><li>[ ] Book et værelse i 2-3 timer</li><li>[ ] Inviter 6-12 deltagere</li><li>[ ] Bogmærk materialesider (se <a href="/da/mental-journey/materialer">Materialer</a>)</li><li>[ ] Gennemgå denne vejledning grundigt</li><li>[ ] Forbered flipover eller whiteboard</li></ul><p><strong>1 dag før:</strong></p><ul><li>[ ] Bekræft fremmøde</li><li>[ ] Opsætningsrum (siddepladser i rundkreds)</li><li>[ ] Test enhver teknologi (slides osv.)</li><li>[ ] Forbered materialer</li></ul><p><strong>1 time før:</strong></p><ul><li>[ ] Ankom tidligt</li><li>[ ] Arranger siddepladser i en cirkel</li><li>[ ] Opsætning af materialer</li><li>[ ] Centrer dig selv</li></ul><h3 id="din-rolle-som-facilitator" tabindex="-1">Din rolle som facilitator <a class="header-anchor" href="#din-rolle-som-facilitator" aria-label="Permalink to &quot;Din rolle som facilitator&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Vigtig</p><p>Du er <strong>ikke</strong> en terapeut eller teknisk coach. Du er en <strong>facilitator</strong>, der:</p><ul><li>Guidediskussion</li><li>Skaber et trygt rum</li><li>Forbinder koncepter med oplevelser</li><li>Styrer gruppedynamik</li></ul></div><p><strong>Nøglefærdigheder:</strong></p><ul><li>Aktiv lytning</li><li>Neutral tilstedeværelse</li><li>Håndtering af forskellige personligheder</li><li>At vide, hvornår man skal videre</li></ul><h3 id="detaljeret-sessionsplan" tabindex="-1">Detaljeret sessionsplan <a class="header-anchor" href="#detaljeret-sessionsplan" aria-label="Permalink to &quot;Detaljeret sessionsplan&quot;">​</a></h3><hr><h4 id="del-1-introduktion-20-minutter" tabindex="-1">Del 1: Introduktion (20 minutter) <a class="header-anchor" href="#del-1-introduktion-20-minutter" aria-label="Permalink to &quot;Del 1: Introduktion (20 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Skab psykologisk tryghed</li><li>Sæt forventninger</li><li>Opbyg gruppeforbindelse</li></ul><p><strong>Manuskript:</strong></p><p>&quot;Velkommen alle sammen. Denne session handler om det mentale spil petanque - de tanker, følelser og mønstre, der påvirker din præstation.&quot;</p><p><strong>Grundregler:</strong></p><ol><li>Det, der deles her, forbliver her</li><li>Ingen dom over andres oplevelser</li><li>Deltagelse er frivillig</li><li>Der er ingen forkerte svar</li></ol><p><strong>Hurtig runde:</strong> Navn, hvor længe du har spillet, én mental udfordring du står over for.</p><p><strong>Noter til underviser:</strong></p><ul><li>Gå først til at modellere sårbarhed</li><li>Hold introduktionerne korte (1 minut hver)</li><li>Bemærk fælles temaer</li><li>Valider alle svar</li></ul><hr><h4 id="del-2-zone-flowtilstanden-40-minutter" tabindex="-1">Del 2: Zone-/flowtilstanden (40 minutter) <a class="header-anchor" href="#del-2-zone-flowtilstanden-40-minutter" aria-label="Permalink to &quot;Del 2: Zone-/flowtilstanden (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Forstå flowtilstande</li><li>Anerkend teknisk vs. flow-tilstand</li><li>Lær &quot;switch&quot;-konceptet</li></ul><p><strong>Åbningsspørgsmål:</strong> &quot;Tænk på en gang, hvor du spillede din bedste petanque. Hvordan føltes det? Hvad var anderledes?&quot;</p><p><strong>Diskussionsspørgsmål:</strong></p><ol><li>&quot;Hvor mange af jer har haft spil, hvor alt bare klikkede?&quot;</li><li>&quot;Hvad tænkte du på i de øjeblikke?&quot;</li><li>&quot;Hvordan er det anderledes end når du kæmper?&quot;</li></ol><p><strong>Vigtige undervisningspunkter:</strong></p><p>Brug whiteboard til at tegne:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Øvelse: Skiftet (10 minutter)</strong></p><p>&quot;Lad os øve skifteøjeblikket:</p><ol><li>Stå op</li><li>Forestil dig, at du er uden for cirklen - tænk på et skud</li><li>Tag en indånding</li><li>Træd frem (ind i en imaginær cirkel)</li><li>Slip analysen, når du træder</li><li>Fokuser kun på et imaginært mål&quot;</li></ol><p><strong>Opsummering:</strong></p><ul><li>&quot;Hvad bemærkede du?&quot;</li><li>&quot;Var det let eller svært at give slip på tankerne?&quot;</li><li>&quot;Hvordan kan dette gælde i rigtige spil?&quot;</li></ul><hr><h4 id="del-3-pause-10-minutter" tabindex="-1">Del 3: Pause (10 minutter) <a class="header-anchor" href="#del-3-pause-10-minutter" aria-label="Permalink to &quot;Del 3: Pause (10 minutter)&quot;">​</a></h4><p><strong>Facilitatorhandlinger:</strong></p><ul><li>Opfordr til uformel diskussion</li><li>Bemærk gruppeenergi</li><li>Forbered dig på næste afsnit</li></ul><hr><h4 id="del-4-den-indre-kritiker-40-minutter" tabindex="-1">Del 4: Den indre kritiker (40 minutter) <a class="header-anchor" href="#del-4-den-indre-kritiker-40-minutter" aria-label="Permalink to &quot;Del 4: Den indre kritiker (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Genkend negative selvsnakmønstre</li><li>Skeln mellem indre kritiker og indre coach</li><li>Øv neutral observation</li></ul><p><strong>Åbning:</strong> &quot;Vi har alle en indre stemme, der kommenterer vores præstation. Nogle gange er den hjælpsom, nogle gange er den hård. Lad os udforske det.&quot;</p><p><strong>Øvelse: Indre kritiker-opgørelse (15 minutter)</strong></p><p>&quot;Skriv ned på dit papir:&quot;</p><ol><li>Hvad din indre stemme siger efter et dårligt kast</li><li>Hvad det siger, når du er under pres</li><li>Hvad det siger om dine evner&quot;</li></ol><p><em>Giv 5 minutter til at skrive</em></p><p>&quot;Hvem er villig til at dele ét eksempel?&quot;</p><p><strong>Noter til underviser:</strong></p><ul><li>Normaliser hård selvsnak</li><li>Forsøg ikke at &quot;fikse&quot; nogen</li><li>Led efter fælles mønstre</li></ul><p><strong>Undervisning: Indre kritiker vs. Indre coach (15 minutter)</strong></p><p>Tegn to kolonner på tavlen:</p><table tabindex="0"><thead><tr><th>Indre kritiker</th><th>Indre træner</th></tr></thead><tbody><tr><td>&quot;Hvordan kunne du overse det?!&quot;</td><td>&quot;Den gik til venstre&quot;</td></tr><tr><td>&quot;Du kvæles altid&quot;</td><td>&quot;Lad os prøve igen&quot;</td></tr><tr><td>&quot;Du er forfærdelig&quot;</td><td>&quot;Hvad kan jeg lære?&quot;</td></tr></tbody></table><p><strong>Diskussion:</strong></p><ul><li>&quot;Læg mærke til forskellen?&quot;</li><li>&quot;Hvilken stemme hjælper præstationen?&quot;</li><li>&quot;Kan du ændre stemmen?&quot;</li></ul><p><strong>Øvelse: Omformulering (10 minutter)</strong></p><p>&quot;Tag en af dine Indre Kritiker-udsagn. Hvordan ville en Indre Coach sige den?&quot;</p><p>Del eksempler.</p><hr><h4 id="del-5-praktiske-værktøjer-40-minutter" tabindex="-1">Del 5: Praktiske værktøjer (40 minutter) <a class="header-anchor" href="#del-5-praktiske-værktøjer-40-minutter" aria-label="Permalink to &quot;Del 5: Praktiske værktøjer (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Lær 3-åndedrætsnulstilling</li><li>Lav en simpel rutine før optagelserne</li><li>Forstå fejlrettelse</li></ul><p><strong>Værktøj 1: Nulstilling af 3 åndedræt (10 minutter)</strong></p><p>&quot;Dette er din nødknap til nulstilling. Brug den, når du mærker trykket vokse.&quot;</p><p><strong>Demonstrere:</strong></p><ol><li>Træk vejret ind i 4 tællinger</li><li>Hold i 2 tællinger</li><li>Pust ud i 6 tællinger</li><li>Gentag 3 gange</li></ol><p>&quot;Lad os øve os sammen nu.&quot;</p><p><em>Led gruppen gennem 3 cyklusser</em></p><p><strong>Opsummering:</strong></p><ul><li>&quot;Hvad bemærkede du i din krop?&quot;</li><li>&quot;Hvornår kan du bruge dette?&quot;</li></ul><p><strong>Værktøj 2: Simpel rutine før optagelse (15 minutter)</strong></p><p>&quot;En rutine hjælper dig med at skifte fra planlægning til udførelse konsekvent.&quot;</p><p><strong>Grundlæggende struktur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Øvelse:</strong> &quot;Lav din egen 3-trinsrutine. Skriv den ned.&quot;</p><p>Del eksempler.</p><p><strong>Værktøj 3: Protokol til fejlretning (15 minutter)</strong></p><p>&quot;Elitespillere laver ikke færre fejl. De kommer sig hurtigere.&quot;</p><p><strong>3-trinsprotokol:</strong></p><ol><li><strong>Observer</strong> - Angiv faktum neutralt (&quot;Det gik til venstre&quot;)</li><li><strong>Lær</strong> - Uddrag information (&quot;Vinden stærkere end jeg troede&quot;)</li><li><strong>Nulstil</strong> - Bevæg dig fremad (3-åndedrætsnulstilling, øjne fremad)</li></ol><p><strong>Praksis:</strong> &quot;Tænk på en nylig fejltagelse. Gennemgå de 3 trin.&quot;</p><hr><h4 id="del-6-integration-og-afslutning-20-minutter" tabindex="-1">Del 6: Integration og afslutning (20 minutter) <a class="header-anchor" href="#del-6-integration-og-afslutning-20-minutter" aria-label="Permalink to &quot;Del 6: Integration og afslutning (20 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Konsolider læring</li><li>Opret handlingsplaner</li><li>Tilvejebring ressourcer</li></ul><p><strong>Refleksionsspørgsmål:</strong></p><ol><li>&quot;Hvilken indsigt tager du med dig?&quot;</li><li>&quot;Hvad er én ting, du vil prøve i denne uge?&quot;</li><li>&quot;Hvilke spørgsmål er der stadig?&quot;</li></ol><p><strong>Handlingsplanlægning (10 minutter)</strong></p><p>&quot;På dit uddelingsark skal du skrive:&quot;</p><ol><li>En teknik du skal øve dig på i denne uge</li><li>Hvornår/hvornår du skal øve det</li><li>Hvordan du vil følge dine fremskridt&quot;</li></ol><p><strong>Ressourcer:</strong></p><ul><li>Uddel et opsummeringsark</li><li>Del hjemmeside: carreau.app</li><li>Anbefalet startmodul: <a href="/da/uddannelse/zonen/">Zonen</a></li></ul><p><strong>Slutning af cirklen:</strong> &quot;Et ord til at beskrive, hvordan du har det lige nu.&quot;</p><p><strong>Slutord:</strong> &quot;Mental træning er en færdighed som enhver anden - det kræver øvelse. Start småt, vær tålmodig med dig selv, og læg mærke til, hvad der ændrer sig. Tak for din åbenhed i dag.&quot;</p><hr><h3 id="tips-til-facilitatorer" tabindex="-1">Tips til facilitatorer <a class="header-anchor" href="#tips-til-facilitatorer" aria-label="Permalink to &quot;Tips til facilitatorer&quot;">​</a></h3><h4 id="handtering-af-vanskelige-situationer" tabindex="-1">Håndtering af vanskelige situationer <a class="header-anchor" href="#handtering-af-vanskelige-situationer" aria-label="Permalink to &quot;Håndtering af vanskelige situationer&quot;">​</a></h4><p><strong>Hvis nogen dominerer:</strong></p><ul><li>&quot;Tak til [navn]. Lad os høre fra andre.&quot;</li><li>Brug struktureret turtagning</li></ul><p><strong>Hvis nogen er imod:</strong></p><ul><li>Ikke skændtes</li><li>&quot;Det er et gyldigt perspektiv. Hvad mener andre?&quot;</li><li>Afstem med deres bekymring</li></ul><p><strong>Hvis nogen bliver følelsesladet:</strong></p><ul><li>Normaliser det</li><li>&quot;Dette rører ved noget virkeligt. Tak fordi du deler.&quot;</li><li>Forsøg ikke at reparere</li></ul><p><strong>Hvis diskussionen går i stå:</strong></p><ul><li>Brug specifikke prompts</li><li>Del dit eget eksempel</li><li>Gå til en øvelse</li></ul><h4 id="energistyring" tabindex="-1">Energistyring <a class="header-anchor" href="#energistyring" aria-label="Permalink to &quot;Energistyring&quot;">​</a></h4><p><strong>Høj energi:</strong> Brug øvelser og bevægelse <strong>Lav energi:</strong> Stil provokerende spørgsmål <strong>Spredt:</strong> Bring tilbage til strukturen <strong>Spændt:</strong> Brug humor eller pause</p><h3 id="efter-sessionen-1" tabindex="-1">Efter sessionen <a class="header-anchor" href="#efter-sessionen-1" aria-label="Permalink to &quot;Efter sessionen&quot;">​</a></h3><p><strong>Opfølgning:</strong></p><ul><li>Send en oversigtsmail inden for 24 timer</li><li>Inkluder links til ressourcer</li><li>Tilbyd at besvare spørgsmål</li><li>Planlæg valgfri opfølgningssession</li></ul><p><strong>Selvrefleksion:</strong></p><ul><li>Hvad fungerede godt?</li><li>Hvad ville du ændre?</li><li>Hvad overraskede dig?</li><li>Hvad lærte du?</li></ul>',118)),n(f),g[5]||(g[5]=a('<hr><h2 id="materialer" tabindex="-1">Materialer <a class="header-anchor" href="#materialer" aria-label="Permalink to &quot;Materialer&quot;">​</a></h2><ul><li><a href="/da/mental-rejse/materialer#deltagervejledning">Deltagervejledning</a></li><li><a href="/da/mental-rejse/materialer#facilitator-slides">Facilitator-slides</a></li><li><a href="/da/mental-rejse/materialer#opsummeringsark">Opsummeringsark</a></li><li><a href="/da/mental-rejse/materialer#øvelsesark">Øvelsesark</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Klar til at facilitere?</p><ol><li>Gennemgå denne vejledning grundigt</li><li>Download materialer</li><li>Øv øvelserne selv</li><li>Planlæg din session</li><li>Stol på processen</li></ol></div>',5))])}]]);export{g as __pageData,p as default};
